function mostVowels(s: string, k: number): number {
  const isVowel = (c: string) => "aeiou".includes(c);
  let best = 0;
  for (let i = 0; i + k <= s.length; i++) {
    let c = 0;
    for (let j = i; j < i + k; j++) if (isVowel(s[j])) c++;
    best = Math.max(best, c);
  }
  return best;
}

